create policy segeda_backups_admin_read on storage.objects for select to authenticated using (bucket_id='segeda-backups' and (select auth.uid()) in (select user_id from public.segeda_admins));
create policy segeda_backups_admin_insert on storage.objects for insert to authenticated with check (bucket_id='segeda-backups' and (select auth.uid()) in (select user_id from public.segeda_admins));
create policy segeda_backups_admin_update on storage.objects for update to authenticated using (bucket_id='segeda-backups' and (select auth.uid()) in (select user_id from public.segeda_admins)) with check (bucket_id='segeda-backups' and (select auth.uid()) in (select user_id from public.segeda_admins));
